def f(n):
    if n == 0:
        return 0
    return n + f(n - 1)

print(f(4))

def fact(n):
    if n == 0:
        return 0
    return n * fact(n - 1)

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(6))
